  ('9f6d17ed-be66-4c54-bfe8-fa5848e1afd2', 'f7c04184-b861-407b-aa09-b734561ae275', 'cb555b69-01b5-407c-9b71-eb6015992ca2', 'Fast lunch, clean flavours, and the roast skin had a nice bite.', '2026-03-31 01:00:00.000000', NULL, 0, 1, false, 'Quick Chicken Rice Stop', false, false, NULL, true),
  ('ce062d57-4be4-4785-aba8-924fe451dbb3', '2bc7840b-8556-48bb-ab61-bf2889a969d1', '045ad4a1-3ee4-4375-b339-ea9ad2392e92', 'A little messy, very satisfying, and worth ordering with extra fries. #burger #western', '2026-03-30 06:00:00.000000', NULL, 2, 0, false, 'Fries and Burger Combo', false, false, NULL, true),
  ('ed172bbd-48d9-41e3-8a36-05d7bd0660ca', 'b91e05ec-e345-446e-8f1d-d18c37d4ab85', '571c483e-615d-419d-978d-e4214f35ebd9', 'This bowl hit the spot after a long day. Warm, savoury, and properly comforting.', '2026-03-30 02:00:00.000000', NULL, 2, 1, false, 'Comfort Bowl After Work', false, false, NULL, true)
